    /**
     * Tests getting all Quarantines.
     *
     * @return    Collection
     */
    public List<Quarantine> testGetAll() throws Throwable {
    LOGGER.info( "QuarantineTest:testGetAll() - Retrieving Collection of Quarantines:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Quarantine : " );
    List<Quarantine> collection  = null;

    try {
        // call the static get method on the QuarantineService
        collection = service.getAllQuarantine();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Quarantine currEntity  = null;
            Iterator<Quarantine> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getQuarantineId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

